async def act(page):
    """
    From the current Manage Products grid state, find and open the Frankie Sweatshirt product edit page,
    open the Associated / Configurations flow and add Color = Blue for Size = S and Size = M,
    then save the product. All interactions use accessibility-role selectors and .select_option where appropriate.
    """
    import asyncio

    # Helper: try clicking any control by role within an optional scope
    async def try_click_any(scope, role, names):
        for n in names:
            try:
                await scope.get_by_role(role, name=n).click()
                return True
            except Exception:
                continue
        return False

    # 1) Close any blocking popup if present (try common close controls). Use page-level scope.
    await try_click_any(page, "button", ["×", "Close", "Close dialog", "Dismiss", "OK", "Cancel"])
    try:
        await page.keyboard.press("Escape")
    except Exception:
        pass

    # 2) Click the Search button inside the cell labeled "Reset Filter Search" to refresh the filtered results
    try:
        # scope the click to the cell that contains the Search button to avoid ambiguity
        reset_cell = page.get_by_role("cell", name="Reset Filter Search")
        await reset_cell.get_by_role("button", name="Search").click()
        await page.wait_for_load_state("networkidle")
    except Exception:
        # fallback: try a top-level Search button
        try:
            await page.get_by_role("button", name="Search").click()
            await page.wait_for_load_state("networkidle")
        except Exception:
            # If Search can't be clicked, wait briefly for UI to settle
            await asyncio.sleep(1)

    # 3) Locate the product row for "Frankie Sweatshirt" and get its Edit link href
    product_href = None
    try:
        frankie_row = page.get_by_role("row").filter(has=page.get_by_role("cell", name="Frankie Sweatshirt"))
        edit_link = frankie_row.get_by_role("link", name="Edit")
        href = await edit_link.get_attribute("href")
        if href:
            product_href = href
    except Exception:
        product_href = None

    # 4) Fallback: try a top-level link named exactly "Frankie Sweatshirt"
    if not product_href:
        try:
            l = page.get_by_role("link", name="Frankie Sweatshirt")
            href = await l.get_attribute("href")
            if href:
                product_href = href
        except Exception:
            product_href = None

    # 5) If we still don't have an href, as a last resort click the product link (this would navigate away and must be last action)
    if not product_href:
        try:
            await page.get_by_role("link", name="Frankie Sweatshirt").click()
            return
        except Exception:
            # Cannot locate product; stop
            return

    # 6) Navigate to the product edit page (use goto so we can continue interacting)
    await page.goto(product_href)
    await page.wait_for_load_state("networkidle")

    # 7) Close any popup on the edit page if present
    await try_click_any(page, "button", ["×", "Close", "Dismiss", "Cancel"])
    try:
        await page.keyboard.press("Escape")
    except Exception:
        pass

    # 8) Open the Associated / Configurations tab/section (try several candidate labels and roles)
    assoc_candidates = [
        "Associated Products",
        "Associated Products / Variations",
        "Associated",
        "Configurations",
        "Configurable Product Variations",
        "Associated Items",
        "Product Variations",
    ]
    assoc_opened = False
    for name in assoc_candidates:
        try:
            await page.get_by_role("tab", name=name).click()
            assoc_opened = True
            break
        except Exception:
            try:
                await page.get_by_role("link", name=name).click()
                assoc_opened = True
                break
            except Exception:
                try:
                    await page.get_by_role("button", name=name).click()
                    assoc_opened = True
                    break
                except Exception:
                    continue
    if assoc_opened:
        await asyncio.sleep(0.8)

    # 9) Trigger the Create Configurations / Create Products flow (several possible button labels)
    create_btns = [
        "Create Configurations",
        "Create Configurations...",
        "Create Products",
        "Create Product",
        "Add Product",
        "Add New Product",
        "Create Variations",
    ]
    for name in create_btns:
        try:
            await page.get_by_role("button", name=name).click()
            await asyncio.sleep(0.9)
            break
        except Exception:
            continue

    # 10) In the create-configurations wizard: select attributes Color and Size (checkboxes or similar)
    try:
        try:
            await page.get_by_role("checkbox", name="Color").check()
        except Exception:
            pass
        try:
            await page.get_by_role("checkbox", name="Size").check()
        except Exception:
            pass
    except Exception:
        pass

    # Move to next step of wizard
    await try_click_any(page, "button", ["Next", "Continue", "Next Step", "Continue to Step 2"])
    await asyncio.sleep(0.7)

    # 11) In values selection, choose Color = Blue and Sizes = S and M (try combobox or checkboxes)
    try:
        # Color selection
        try:
            await page.get_by_role("combobox", name="Color").select_option(label="Blue")
        except Exception:
            try:
                await page.get_by_role("checkbox", name="Blue").check()
            except Exception:
                pass

        # Size selection: attempt combobox multi-select by selecting both sequentially, else checkboxes
        try:
            size_cb = page.get_by_role("combobox", name="Size")
            await size_cb.select_option(label="S")
            await asyncio.sleep(0.2)
            await size_cb.select_option(label="M")
        except Exception:
            try:
                await page.get_by_role("checkbox", name="S").check()
            except Exception:
                pass
            try:
                await page.get_by_role("checkbox", name="M").check()
            except Exception:
                pass
    except Exception:
        pass

    # 12) Generate/create the configurations and confirm
    await try_click_any(page, "button", ["Next", "Generate", "Create", "Create Products", "Generate Products", "Finish"])
    await asyncio.sleep(1.2)
    await try_click_any(page, "button", ["Apply", "OK", "Done", "Finish", "Create"])
    await asyncio.sleep(0.8)

    # 13) Final: Save the main product to persist changes. Save is expected to navigate away, so it must be the last action.
    save_candidates = ["Save", "Save and Continue Edit", "Save Product"]
    for name in save_candidates:
        try:
            await page.get_by_role("button", name=name).click()
            return
        except Exception:
            continue

    # Fallback save label
    try:
        await page.get_by_role("button", name="Save and Continue").click()
        return
    except Exception:
        return
